<?php
namespace Tests\Feature;
use App\Services\Marketing\{MarketingSceneExecutionPolicy as Policy,MarketingVideoRoutes,MarketingStoryboardAudioRoute};
use Illuminate\Support\Facades\Http;
use Tests\TestCase;

class MarketingSceneExecutionPolicyTest extends TestCase
{
 private function scene():array{return ['seconds'=>9,'message'=>'商品介绍','visual'=>'商品静物展示','voiceover'=>'给自己一刻。','subtitle'=>'','presenter_required'=>false,'director'=>['subject'=>'商品','framing'=>'近景','lighting'=>'自然光','start_state'=>'静物','end_state'=>'静物','motion'=>'固定镜头'],'frames'=>['start_frame'=>['required'=>true,'instruction'=>'原图','person_presence'=>'absent']],'material_plan'=>['mode'=>'single_image','roles'=>['start_frame'],'reason'=>'展示商品','production_route'=>'auto','fidelity'=>'exact_brand','motion_kind'=>'camera_only']];}
 public function test_exact_brand_selects_source_locked_and_separate_voice_without_http():void{Http::preventStrayRequests();$d=app(Policy::class)->decide($this->scene());$this->assertSame('source_locked',$d['route']);$this->assertSame('independent',$d['audio']);$this->assertSame(0,$d['external_video_posts']);Http::assertNothingSent();}
 public function test_action_is_never_silently_replaced_by_a_static_route():void{$s=$this->scene();$s['material_plan']['motion_kind']='action';$d=app(Policy::class)->decide($s);$this->assertSame('needs_review',$d['route']);$this->assertContains('exact_brand_action_conflict',$d['blockers']);}
 public function test_generational_route_cannot_override_exact_fidelity():void{$s=$this->scene();$s['material_plan']['production_route']='generative';$this->assertSame('source_locked',app(Policy::class)->decide($s)['route']);}
 public function test_camera_only_and_unprotected_action_have_distinct_routes():void{$s=$this->scene();$s['material_plan']['fidelity']='standard';$this->assertSame('conservative_motion',app(Policy::class)->decide($s)['route']);$s['material_plan']['motion_kind']='action';$this->assertSame('generative',app(Policy::class)->decide($s)['route']);}
 public function test_required_end_frame_is_not_discarded_for_local_route():void{$s=$this->scene();$s['material_plan']['roles'][]='end_frame';$this->assertSame('needs_review',app(Policy::class)->decide($s)['route']);}
 public function test_speech_caption_and_rhythm_edits_reuse_pixels_but_visual_edits_do_not():void{$a=$this->scene();$b=$a;$b['voiceover']='新的说法。';$b['subtitle']='新的字幕';$b['seconds']=10;$b['rhythm']=['speech_start'=>.5,'speech_end'=>7];$impact=app(Policy::class)->impact($a,$b,[]);$this->assertSame([],$impact['images']);$this->assertTrue($impact['voice']);$this->assertTrue($impact['composition']);$b['director']['subject']='另一件商品';$this->assertSame(['start_frame'],app(Policy::class)->impact($a,$b,[])['images']);}
 public function test_unknown_local_rate_blocks_selection_before_provider_request():void{Http::preventStrayRequests();$s=$this->scene();$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);try{app(MarketingVideoRoutes::class)->select($s+['execution_policy_version'=>Policy::VERSION],'ordinary');}finally{Http::assertNothingSent();}}
 public function test_independent_requirement_never_falls_back_to_native():void{Http::preventStrayRequests();config(['marketing.storyboard.audio.native'=>['model'=>'seedance-1.5-pro','customer_billing'=>true,'script_request_supported'=>true,'languages'=>['zh-MY']],'marketing.storyboard.voices'=>[]]);$h=['require_independent_audio'=>true,'scene_map'=>[$this->scene()],'source_context'=>['language'=>'zh-MY'],'profile'=>['voice'=>['mode'=>'auto']]];$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);try{app(MarketingStoryboardAudioRoute::class)->select($h,['model'=>'seedance-1.5-pro','customer_billing'=>true,'cap_microusd'=>500000]);}finally{Http::assertNothingSent();}}
 public function test_validated_material_plan_roundtrips_ai_route_fields():void{$s=$this->scene();$s=app(\App\Services\Marketing\MarketingStoryboardContract::class)->content($s);$this->assertSame('exact_brand',$s['material_plan']['fidelity']);$this->assertSame('camera_only',$s['material_plan']['motion_kind']);}
 public function test_authorized_server_rate_selects_local_without_uploads_or_video_calls():void{Http::preventStrayRequests();config(['marketing.production.local_scene_rate'=>['cap_microusd'=>0,'version'=>'fake-included-compute','pricing_verified_at'=>now()->toIso8601String(),'valid_until'=>now()->addHour()->toIso8601String()],'marketing.production.speed_ffmpeg_binary'=>__FILE__]);$r=app(MarketingVideoRoutes::class)->select($this->scene()+['execution_policy_version'=>Policy::VERSION],'ordinary');$this->assertTrue($r['local']);$this->assertSame('local-image-compose',$r['video']['model']);$this->assertSame(['start_frame'],$r['image_roles']);$this->assertSame('source_locked',$r['execution_policy']['route']);Http::assertNothingSent();}
 public function test_legacy_native_route_retains_its_saved_contract():void{config(['marketing.storyboard.audio.native'=>['model'=>'seedance-1.5-pro','customer_billing'=>true,'script_request_supported'=>true,'languages'=>['zh-MY']],'marketing.storyboard.voices'=>[]]);$h=['scene_map'=>[$this->scene()],'source_context'=>['language'=>'zh-MY'],'profile'=>['voice'=>['mode'=>'auto']]];$this->assertSame('native',app(MarketingStoryboardAudioRoute::class)->select($h,['model'=>'seedance-1.5-pro','customer_billing'=>true,'cap_microusd'=>500000])['route']);}
 public function test_generic_brand_notes_do_not_turn_tea_garden_into_packaging_shot():void{$s=$this->scene();unset($s['material_plan']);$s['director']['subject']='高山茶园的绿叶';$s['visual']='茶园绿叶，包装文字由片尾处理';$s['scene_design']['product']='保留包装资料供片尾使用';$this->assertSame('generative',app(Policy::class)->decide($s)['route']);$s['director']['subject']='干茶叶、透明茶杯；不出现人物、包装或宣传文字。';$this->assertSame('generative',app(Policy::class)->decide($s)['route']);}
 public function test_camera_only_label_cannot_drop_an_explicit_pour_action():void{$s=$this->scene();$s['material_plan']['fidelity']='standard';$s['director']['motion']='pour tea into the cup';$this->assertSame('needs_review',app(Policy::class)->decide($s)['route']);}
}
